/// <summary>
/// Helper class for Delegate
/// MPJ_24248 Pricing Data Extract
/// </summary>
class METMarkupAutoSetupHelper
{
    FormRun         formRun;
    FormDataSource  markupAutoTable_ds;
    MarkupAutoTable markupAutoTable;
    FormButtonGroupControl  buttonGroupcontrol;

}

Method.Source:
/// <summary>
/// Handler method for Form Edit button delegate
/// Having this method in Form_extension class gave a compile error. Added here as work around
/// </summary>
public void editModeSwitched()
{
    formRun.metEditModeSwitched();
}

    /// <summary>
    /// Initialise new object
    /// </summary>
    /// <param name = "_formRun">form run</param>
    /// <returns>class object</returns>
    static METMarkupAutoSetupHelper newFromFormRun(FormRun _formRun)
    {
        METMarkupAutoSetupHelper markupAutoSetupHelper = new METMarkupAutoSetupHelper();

        markupAutoSetupHelper.parmFormRun(_formRun);

        return markupAutoSetupHelper;
    }

/// <summary>
/// parm Form object
/// </summary>
/// <param name = "_formRun">Form run</param>
/// <returns>Form Run object</returns>
public FormRun parmFormRun(FormRun _formRun = FormRun)
{
    formRun = _formRun;
    return formRun;
}

    /// <summary>
    /// CB748_PricingConditions
    /// Updating rebate controls called at form init and when selectionChange for HeadingLine
    /// </summary>
    /// <param name = "_moduleType"></param>
    /// <param name = "_moduleCategory"></param>
    public void updateRebateControlsVisible(MarkupModuleType _moduleType, HeadingLine _moduleCategory)
    {
        boolean isVisible = _moduleType == MarkupModuleType::Vend && _moduleCategory == HeadingLine::Line;

        // cannot use datasource fields for some reason, using control instead
        FormDateControl MarkupAutoLine_FromDate = formRun.design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoLine_FromDate));
        FormDateControl MarkupAutoLine_ToDate = formRun.design().controlName(formControlStr(MarkupAutoSetup, MarkupAutoLine_ToDate));

        MarkupAutoLine_FromDate.visible(isVisible);
        MarkupAutoLine_FromDate.enabled(isVisible);
        MarkupAutoLine_ToDate.visible(isVisible);
        MarkupAutoLine_ToDate.enabled(isVisible);        

        FormDataSource markupAutoLine_ds = formRun.dataSource(tableStr(MarkupAutoLine));
        // show/hide custom fields
        markupAutoLine_ds.object(fieldNum(MarkupAutoLine, METPurchGroupId)).visible(isVisible);
        markupAutoLine_ds.object(fieldNum(MarkupAutoLine, METRebateTermEffectiveDate)).visible(isVisible);
    }

    /// <summary>
    /// CB748_PricingConditions
    /// Update rebate controls enabled/mandatory at markupAutoLineDS.active and MarkupCode.modified
    /// </summary>
    /// <param name = "_moduleType"></param>
    /// <param name = "_moduleCategory"></param>
    public void updateRebateControlsEnabled(FormDataSource _formDataSource)
    {
        // Enable custom fields if is rebate code and Vend and Line
        MarkupAutoLine markupAutoLine = _formDataSource.cursor();
        MarkupTable markupTable = markupAutoLine.markupTable();

        boolean allowEdit = markupTable.METIsRebateCode
                         && markupAutoLine.ModuleType == MarkupModuleType::Vend
                         && markupAutoLine.ModuleCategory == HeadingLine::Line;

        _formDataSource.object(fieldNum(MarkupAutoLine, METPurchGroupId)).allowEdit(allowEdit);
        _formDataSource.object(fieldNum(MarkupAutoLine, METPurchGroupId)).mandatory(allowEdit);
        _formDataSource.object(fieldNum(MarkupAutoLine, METRebateTermEffectiveDate)).allowEdit(allowEdit);
        _formDataSource.object(fieldNum(MarkupAutoLine, FromDate)).mandatory(allowEdit);
    }
